package clock

import "time"

// Clock abstracts time for tests.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Real returns the wall clock.
func Real() Clock { return realClock{} }

// Fixed returns a clock frozen at t.
type Fixed time.Time

func (f Fixed) Now() time.Time { return time.Time(f) }

//! Line tokenizer used by the config parser.

use std::fmt;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Token<'a> {
    Ident(&'a str),
    Number(i64),
    Str(&'a str),
    Equals,
    Newline,
}

#[derive(Debug, PartialEq, Eq)]
pub struct LexError {
    pub offset: usize,
    pub msg: &'static str,
}

impl fmt::Display for LexError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{} at byte {}", self.msg, self.offset)
    }
}

pub fn tokenize(src: &str) -> Result<Vec<Token<'_>>, LexError> {
    let bytes = src.as_bytes();
    let mut out = Vec::new();
    let mut i = 0;
    while i < bytes.len() {
        match bytes[i] {
            b' ' | b'\t' => i += 1,
            b'\n' => { out.push(Token::Newline); i += 1; }
            b'=' => { out.push(Token::Equals); i += 1; }
            b'#' => while i < bytes.len() && bytes[i] != b'\n' { i += 1 },
            b'"' => {
                let start = i + 1;
                let end = src[start..].find('"').ok_or(LexError { offset: i, msg: "unterminated string" })?;
                out.push(Token::Str(&src[start..start + end]));
                i = start + end + 1;
            }
            b'0'..=b'9' | b'-' => {
                let start = i;
                i += 1;
                while i < bytes.len() && bytes[i].is_ascii_digit() { i += 1 }
                let n = src[start..i].parse().map_err(|_| LexError { offset: start, msg: "bad number" })?;
                out.push(Token::Number(n));
            }
            c if c.is_ascii_alphabetic() || c == b'_' => {
                let start = i;
                while i < bytes.len() && (bytes[i].is_ascii_alphanumeric() || bytes[i] == b'_') { i += 1 }
                out.push(Token::Ident(&src[start..i]));
            }
            _ => return Err(LexError { offset: i, msg: "unexpected byte" }),
        }
    }
    Ok(out)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn simple_assignment() {
        let toks = tokenize("port = 8080\n").unwrap();
        assert_eq!(toks, vec![Token::Ident("port"), Token::Equals, Token::Number(8080), Token::Newline]);
    }

    #[test]
    fn unterminated_string() {
        assert_eq!(tokenize("name = \"abc").unwrap_err().msg, "unterminated string");
    }
}

package httpapi

import (
	"encoding/json"
	"errors"
	"net/http"
	"strconv"

	"github.com/gigi/tilemux/internal/tiles"
)

type Handler struct {
	Store tiles.Store
}

func (h *Handler) Routes() http.Handler {
	mux := http.NewServeMux()
	mux.HandleFunc("GET /tiles/{z}/{x}/{y}", h.getTile)
	mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, _ *http.Request) {
		w.WriteHeader(http.StatusNoContent)
	})
	return mux
}

func parseCoord(r *http.Request, name string) (int, error) {
	v, err := strconv.Atoi(r.PathValue(name))
	if err != nil || v < 0 {
		return 0, errors.New("invalid " + name)
	}
	return v, nil
}

func (h *Handler) getTile(w http.ResponseWriter, r *http.Request) {
	var coords [3]int
	for i, name := range []string{"z", "x", "y"} {
		v, err := parseCoord(r, name)
		if err != nil {
			writeError(w, http.StatusBadRequest, err.Error())
			return
		}
		coords[i] = v
	}
	data, err := h.Store.Get(r.Context(), coords[0], coords[1], coords[2])
	switch {
	case errors.Is(err, tiles.ErrNotFound):
		writeError(w, http.StatusNotFound, "tile not found")
		return
	case err != nil:
		writeError(w, http.StatusInternalServerError, "store error")
		return
	}
	w.Header().Set("Content-Type", "application/vnd.mapbox-vector-tile")
	w.Header().Set("Cache-Control", "public, max-age=3600")
	_, _ = w.Write(data)
}

func writeError(w http.ResponseWriter, code int, msg string) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(code)
	_ = json.NewEncoder(w).Encode(map[string]string{"error": msg})
}

terraform {
  required_version = ">= 1.6"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.40"
    }
  }
  backend "s3" {
    bucket = "edge-cluster-tfstate"
    key    = "staging/network.tfstate"
    region = "eu-west-3"
  }
}

provider "aws" {
  region = var.region
}

variable "region" {
  type    = string
  default = "eu-west-3"
}

variable "azs" {
  type    = list(string)
  default = ["eu-west-3a", "eu-west-3b", "eu-west-3c"]
}

resource "aws_vpc" "main" {
  cidr_block           = "10.40.0.0/16"
  enable_dns_hostnames = true
  tags = { Name = "edge-staging" }
}

resource "aws_subnet" "private" {
  count             = length(var.azs)
  vpc_id            = aws_vpc.main.id
  availability_zone = var.azs[count.index]
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 4, count.index)
  tags = { Name = "edge-private-${count.index}" }
}

resource "aws_subnet" "public" {
  count                   = length(var.azs)
  vpc_id                  = aws_vpc.main.id
  availability_zone       = var.azs[count.index]
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 4, count.index + 8)
  map_public_ip_on_launch = true
  tags = { Name = "edge-public-${count.index}" }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id
}

resource "aws_security_group" "nodes" {
  name   = "edge-nodes"
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

output "private_subnet_ids" {
  value = aws_subnet.private[*].id
}

