const currency = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" });

type Line = { id: string; name: string; price: number; qty: number };

function CartLine({ line, onRemove, onQty }: { line: Line; onRemove: () => void; onQty: (q: number) => void }) {
  return (
    <li className="cart-line">
      <span className="cart-line__name">{line.name}</span>
      <input
        type="number"
        min={1}
        max={99}
        value={line.qty}
        aria-label={`Quantity for ${line.name}`}
        onChange={(e) => onQty(Math.max(1, Number(e.target.value) || 1))}
      />
      <span className="cart-line__price">{currency.format(line.price * line.qty)}</span>
      <button type="button" className="link" onClick={onRemove}>
        Remove
      </button>
    </li>
  );
}

export function CartPage() {
  const { items, remove, setQty, status } = useCart();
  const subtotal = useMemo(() => items.reduce((s, i) => s + i.price * i.qty, 0), [items]);
  const shipping = subtotal >= 50 || subtotal === 0 ? 0 : 4.99;

  if (status === "loading") return <Spinner label="Loading cart" />;
  if (items.length === 0) {
    return (
      <EmptyState title="Your cart is empty" action={<Link to="/products">Browse products</Link>} />
    );
  }

  return (
    <section className="cart" aria-labelledby="cart-title">
      <h1 id="cart-title">Cart</h1>
      <ul className="cart__lines">
        {items.map((line) => (
          <CartLine key={line.id} line={line} onRemove={() => remove(line.id)} onQty={(q) => setQty(line.id, q)} />
        ))}
      </ul>
      <dl className="cart__summary">
        <dt>Subtotal</dt>
        <dd>{currency.format(subtotal)}</dd>
        <dt>Shipping</dt>
        <dd>{shipping === 0 ? "Free" : currency.format(shipping)}</dd>
        <dt>Total</dt>
        <dd className="cart__total">{currency.format(subtotal + shipping)}</dd>
      </dl>
      <Link className="button button--primary" to="/checkout">
        Checkout
      </Link>
    </section>
  );
}

