from decimal import Decimal, ROUND_HALF_EVEN

_RATES = {
    ("EUR", "USD"): Decimal("1.08"),
    ("USD", "EUR"): Decimal("0.926"),
    ("GBP", "EUR"): Decimal("1.17"),
    ("EUR", "GBP"): Decimal("0.855"),
}

CENT = Decimal("0.01")


class UnknownRate(KeyError):
    pass


def convert(amount: Decimal, src: str, dst: str) -> Decimal:
    """Convert amount from src to dst using the static table, rounded to cents (banker's rounding)."""
    if src == dst:
        return amount.quantize(CENT, rounding=ROUND_HALF_EVEN)
    try:
        rate = _RATES[(src.upper(), dst.upper())]
    except KeyError as exc:
        raise UnknownRate(f"{src}->{dst}") from exc
    return (amount * rate).quantize(CENT, rounding=ROUND_HALF_EVEN)


def split(total: Decimal, parts: int) -> list[Decimal]:
    """Split total into `parts` amounts that add up exactly, spreading the remainder cent by cent."""
    if parts <= 0:
        raise ValueError("parts must be positive")
    base = (total / parts).quantize(CENT, rounding="ROUND_DOWN")
    out = [base] * parts
    remainder = int((total - base * parts) / CENT)
    for i in range(remainder):
        out[i] += CENT
    return out


def format_money(amount: Decimal, currency: str) -> str:
    symbol = {"EUR": "\u20ac", "USD": "$", "GBP": "\u00a3"}.get(currency, currency + " ")
    sign = "-" if amount < 0 else ""
    return f"{sign}{symbol}{abs(amount):,.2f}"

